"use strict";

const http = require("http");
const https = require("https");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

function browserHeaders(cookie) {
  return {
    "user-agent": UA,
    accept:
      "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
    "accept-language": "en-US,en;q=0.9",
    "accept-encoding": "identity",
    "sec-ch-ua": '"Chromium";v="126", "Google Chrome";v="126", "Not;A=Brand";v="24"',
    "sec-ch-ua-mobile": "?0",
    "sec-ch-ua-platform": '"Windows"',
    "sec-fetch-dest": "document",
    "sec-fetch-mode": "navigate",
    "sec-fetch-site": "none",
    "upgrade-insecure-requests": "1",
    cookie,
  };
}

const cleanUrl = (u) =>
  u ? String(u).replace(/\\u002F/g, "/").replace(/\\/g, "").replace(/&amp;/g, "&") : null;

class Jar {
  constructor() {
    this.map = new Map();
  }
  absorb(headers) {
    const lines = headers && headers["set-cookie"];
    if (!Array.isArray(lines)) return;
    for (const line of lines) {
      const pair = String(line).split(";")[0];
      const i = pair.indexOf("=");
      if (i > 0) this.map.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim());
    }
  }
  toString() {
    return [...this.map.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }
}

function requestOnce(urlStr, jar) {
  return new Promise((resolve, reject) => {
    let parsed;
    try {
      parsed = new URL(urlStr);
    } catch {
      reject(new Error("Invalid URL: " + urlStr));
      return;
    }
    const lib = parsed.protocol === "http:" ? http : https;
    const req = lib.request(
      parsed,
      {
        method: "GET",
        headers: browserHeaders(jar.toString()),
        timeout: 25000,
      },
      (res) => {
        jar.absorb(res.headers);
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () =>
          resolve({
            status: res.statusCode || 0,
            headers: res.headers,
            body: Buffer.concat(chunks).toString("utf8"),
          })
        );
        res.on("error", reject);
      }
    );
    req.on("timeout", () => req.destroy(new Error("Request timed out")));
    req.on("error", reject);
    req.end();
  });
}

async function requestFollowingRedirects(url, jar, maxRedirects = 8) {
  let current = url;
  for (let i = 0; i <= maxRedirects; i++) {
    const res = await requestOnce(current, jar);
    const location = res.headers && res.headers.location;
    if (res.status >= 300 && res.status < 400 && location && i < maxRedirects) {
      current = new URL(location, current).toString();
      continue;
    }
    return { status: res.status, finalUrl: current, html: res.body };
  }
  return { status: 0, finalUrl: current, html: "" };
}

async function fetchPage(url, jar) {
  return requestFollowingRedirects(url, jar);
}

function* jsonBlobs(html) {
  const re = /<script[^>]*type="application\/json"[^>]*>([\s\S]*?)<\/script>/g;
  let m;
  while ((m = re.exec(html))) yield m[1];
}

function walkObjects(node, depth, visit) {
  if (depth > 28) return;
  if (typeof node === "string") {
    const t = node.trim();
    if (
      t.length > 2 &&
      t.length < 2_000_000 &&
      ((t.startsWith("{") && t.endsWith("}")) || (t.startsWith("[") && t.endsWith("]")))
    ) {
      try {
        walkObjects(JSON.parse(t), depth + 1, visit);
      } catch {

      }
    }
    return;
  }
  if (!node || typeof node !== "object") return;
  visit(node);
  for (const v of Object.values(node)) walkObjects(v, depth + 1, visit);
}

function extractMedia(html, wantCode) {
  const candidates = [];
  for (const blob of jsonBlobs(html)) {
    let root;
    try {
      root = JSON.parse(blob);
    } catch {
      continue;
    }
    walkObjects(root, 0, (o) => {
      if (
        !Array.isArray(o) &&
        (o.video_versions || o.image_versions2 || o.carousel_media) &&
        (o.code || o.pk) &&
        o.user
      ) {
        candidates.push(o);
      }
    });
  }
  if (!candidates.length) return null;
  return (
    candidates.find((c) => wantCode && c.code === wantCode && typeof c.video_duration === "number") ||
    candidates.find((c) => wantCode && c.code === wantCode) ||
    candidates.find((c) => typeof c.video_duration === "number") ||
    candidates[0]
  );
}

function bestImage(media) {
  const cands =
    media.image_versions2 && Array.isArray(media.image_versions2.candidates)
      ? media.image_versions2.candidates
      : [];
  if (!cands.length) return null;
  return cands
    .slice()
    .sort((a, b) => (b.width || 0) * (b.height || 0) - (a.width || 0) * (a.height || 0))[0].url;
}

function primaryMedia(media) {
  if (Array.isArray(media.video_versions) && media.video_versions.length) {
    return { url: media.video_versions[0].url, type: "video" };
  }
  const image = bestImage(media);
  if (image) return { url: image, type: "image" };
  if (Array.isArray(media.carousel_media)) {
    for (const child of media.carousel_media) {
      if (child.video_versions && child.video_versions.length) {
        return { url: child.video_versions[0].url, type: "video" };
      }
      const childImage = bestImage(child);
      if (childImage) return { url: childImage, type: "image" };
    }
  }
  return { url: null, type: "image" };
}

function carouselChildren(media) {
  if (!Array.isArray(media.carousel_media) || !media.carousel_media.length) return [];
  const out = [];
  for (const child of media.carousel_media) {
    const m = primaryMedia(child);
    const u = cleanUrl(m.url);
    if (u && !out.some((it) => it.url === u)) out.push({ url: u, type: m.type });
  }
  return out;
}

function parseShortcode(input) {
  const s = String(input || "").trim();
  const m = s.match(/instagram\.com\/(?:reel|reels|p|tv)\/([A-Za-z0-9_-]+)/);
  if (m) return m[1];
  if (/^[A-Za-z0-9_-]{8,15}$/.test(s)) return s;
  return null;
}

module.exports = async function fetchSelf(url, cookie) {
  const code = parseShortcode(url);
  if (!code) throw new Error("Invalid Instagram URL or shortcode");

  const jar = new Jar();
  if (cookie && typeof cookie === "string") {
    for (const part of cookie.split(";")) {
      const i = part.indexOf("=");
      if (i > 0) jar.map.set(part.slice(0, i).trim(), part.slice(i + 1).trim());
    }
  }
  const pageUrl = `https://www.instagram.com/reel/${code}/`;
  let last = null;
  let media = null;
  for (let attempt = 0; attempt < 3 && !media; attempt++) {
    const page = await fetchPage(pageUrl, jar);
    last = page;
    media = extractMedia(page.html, code);
    if (!media && attempt < 2) await new Promise((r) => setTimeout(r, 700));
  }

  if (!media) {
    if (last && /\/accounts\/login/.test(last.finalUrl)) {
      throw new Error("Instagram asked for a login for this post (private or restricted)");
    }
    throw new Error(
      "Could not extract media — the post may be private, deleted, or Instagram changed its page format"
    );
  }

  const primary = primaryMedia(media);
  const downloadUrl = cleanUrl(primary.url);
  if (!downloadUrl) throw new Error("No downloadable media found in Instagram post (self-scrape)");

  const user = media.user || {};

  return {
    success: true,
    source: "Instagram",
    data: {
      shortcode: media.code || code,
      caption: media.caption && media.caption.text ? media.caption.text : "",
      owner: {
        username: user.username || null,
        profile_pic: cleanUrl(user.profile_pic_url) || null,
      },
      download: {
        url: downloadUrl,
        type: primary.type,
        thumbnail: cleanUrl(bestImage(media)) || null,
      },
      carousel: carouselChildren(media),
    },
  };
};
